/**
 * The server's time, for counting down to a deadline the server set
 * (offer presentation spec 2026-10-13, §4.2). `/billing/state` says what
 * time it was when it answered (`serverNow`); the client keeps the skew
 * against its own clock and ticks on the monotonic clock, so changing the
 * phone's clock during a session moves no deadline.
 *
 *   server time at receipt = serverNow + rtt / 2
 *   now() = server time at receipt + (performance.now() − perf at receipt)
 *
 * Some browsers stop the monotonic clock while a phone sleeps, so coming
 * back into view re-anchors on the wall clock with the skew last measured.
 * With no answer yet, the device's own clock stands in.
 */

interface Anchor {
  /** Server milliseconds at the anchor. */
  server: number;
  /** performance.now() at the anchor. */
  perf: number;
  /** server − Date.now() at the anchor: what re-anchoring after a sleep uses. */
  skew: number;
}

let anchor: Anchor | undefined;

function perfNow(): number {
  return typeof performance === 'undefined' ? Date.now() : performance.now();
}

/** Notes the server's time from an answer that took `rttMs` to come back. */
export function noteServerTime(serverNowIso: string | undefined, rttMs: number): void {
  if (serverNowIso === undefined) return;
  const at = Date.parse(serverNowIso);
  if (Number.isNaN(at)) return;
  const server = at + Math.max(0, rttMs) / 2;
  anchor = { server, perf: perfNow(), skew: server - Date.now() };
}

/** The best guess at the server's time now, in milliseconds. */
export function serverNow(): number {
  if (anchor === undefined) return Date.now();
  return anchor.server + (perfNow() - anchor.perf);
}

/** The last stamp `syncStamp` handed out, so stamps never go backwards. */
let lastStamp = 0;

/**
 * The time a queued change is stamped with (the outbox's `clientTs`), on the
 * server's clock. The server takes a settings, word or notebook write only
 * when its `clientTs` is after the stored copy's time, and the copy a new
 * account starts with is stamped by the server's clock at sign-up. A device
 * whose clock was behind the server's (an emulator after the computer slept,
 * a phone set by hand) therefore had every write of its first card answered
 * "merged" with the server's defaults: the introduction's reminder came back
 * off (Android 1.0.75 testing, 24 Oct 2026). Stamped on the server's clock,
 * a change made after sign-up is after it. With no answer from the server
 * yet, the device's own clock stands in, as before. Never earlier than the
 * stamp before it, so re-anchoring cannot make a later edit look older,
 * and never before `notBefore` when the caller knows a time it must follow.
 */
export function syncStamp(notBefore?: number): string {
  const at = Math.max(Math.round(serverNow()), lastStamp + 1, notBefore ?? 0);
  lastStamp = at;
  return new Date(at).toISOString();
}

/** Re-anchors on the wall clock and the last skew (after the page slept). */
export function reanchorServerClock(): void {
  if (anchor === undefined) return;
  anchor = { server: Date.now() + anchor.skew, perf: perfNow(), skew: anchor.skew };
}

/** For tests: forget the server's time. */
export function forgetServerClock(): void {
  anchor = undefined;
  lastStamp = 0;
}

if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') reanchorServerClock();
  });
}
