/**
 * ULID generation. The API accepts client-generated ids on push, so a word
 * created offline keeps its identity when it reaches the server. The format
 * must match the server's: 26 characters of Crockford base32, time-ordered.
 */
const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
const TIME_LEN = 10;
const RANDOM_LEN = 16;

/** Encodes a millisecond timestamp as 10 Crockford base32 characters. */
function encodeTime(ms: number): string {
  let out = '';
  let value = ms;
  for (let i = TIME_LEN - 1; i >= 0; i--) {
    out = (ALPHABET[value % 32] ?? '0') + out;
    value = Math.floor(value / 32);
  }
  return out;
}

/** Encodes 16 characters of randomness. */
function encodeRandom(): string {
  const bytes = new Uint8Array(RANDOM_LEN);
  crypto.getRandomValues(bytes);
  let out = '';
  for (const byte of bytes) out += ALPHABET[byte % 32] ?? '0';
  return out;
}

/** A new ULID, lexicographically sortable by creation time. */
export function newId(now: number = Date.now()): string {
  return encodeTime(now) + encodeRandom();
}

/** Whether a string is a well-formed ULID, as the API validates it. */
export function isId(value: string): boolean {
  return /^[0-9A-HJKMNP-TV-Z]{26}$/.test(value);
}
